import React, { useState } from 'react'
import { Link } from 'react-router-dom'

function NavBar() {
    const [open,setOpne] = useState(false) 
    const linkNames = [
        {"name":"Home",
            "url":"/"
        },
        {"name":"Planets",
            "url":"/planets"
        }
    ]
  return (
    <div className=' bg-white w-full sm:h-16 md:flex md:justify-between text-black p-5'>
        <h1 className=' uppercase font-poppins text-2xl'>solar explore</h1>
        <div className=' md:flex'>
            {
                linkNames.map((item)=>{
                    return <Link className=' ' to={item.url}>{item.name}</Link>
                })
            }
        </div>
    </div>
  )
}

export default NavBar
